  t.Run("info/refs returns 404 for missing repo", func(t *testing.T) {
      srv := newTestServer(t, "gt", "bd")
      req := httptest.NewRequest("GET",
          "/v1/git/missingrig/info/refs?service=git-upload-pack", nil)
      w := httptest.NewRecorder()
